        if n_customers is not None:
            if depot == 0:
                return list(range(1, n_customers + 1))
            return [i for i in range(1, n_customers + 1) if i != depot]
        if is_seq(demands):
            n = len(demands)
            if depot == 0:
                return list(range(1, n))
            return [i for i in range(n) if i != depot]
        return []

    customers = customer_ids()

    def demand(c):
        if type(demands) == dict:
            return demands.get(c, 1)
        if is_seq(demands):
            try:
                if 0 <= c < len(demands):
                    return demands[c]
            except Exception:
                pass
            try:
                if 1 <= c <= len(demands) - 1:
                    return demands[c]
            except Exception:
                pass
        return 1

    def dist(a, b):
        if matrix is not None:
            if type(matrix) == dict:
                if (a, b) in matrix:
                    return matrix[(a, b)]
                if (b, a) in matrix:
                    return matrix[(b, a)]
            else:
                try:
                    return matrix[a][b]
                except Exception:
                    pass
        if coords is not None:
            try:
                ax, ay = coords[a]
                bx, by = coords[b]
                dx = ax - bx
                dy = ay - by
                return (dx * dx + dy * dy) ** 0.5
            except Exception:
                pass
        return abs(a - b)

    def route_load(route):
        s = 0
        for c in route:
            s += demand(c)
        return s

    def route_cost(route):
        if not route:
            return 0
        c = dist(depot, route[0])
        i = 0
        while i + 1 < len(route):
            c += dist(route[i], route[i + 1])
            i += 1
        c += dist(route[-1], depot)
        return c

    def insertion_cost(route, pos, c):
        prev_n = depot if pos == 0 else route[pos - 1]
        next_n = depot if pos == len(route) else route[pos]
        return dist(prev_n, c) + dist(c, next_n) - dist(prev_n, next_n)

    unserved = set(customers)
    routes = []

    # Constructive phase: seed routes by farthest customers, then cheapest feasible insertions.
    while unserved:
        seed = None
        seed_key = None
        for c in unserved:
            d = demand(c)
            key = (dist(depot, c), d, -c)
            if seed is None or key > seed_key:
                seed = c
                seed_key = key
        if seed is None:
            break

        route = [seed]
        load = demand(seed)
        unserved.remove(seed)

        while True:
            best_c = None
            best_key = None
            best_pos = None

            # Try append/insert anywhere; choose cheapest feasible insertion.
            for c in unserved:
                d = demand(c)
                if load + d > capacity:
                    continue
                pos = 0
                while pos <= len(route):
                    inc = insertion_cost(route, pos, c)
                    key = (inc, dist(depot, c), d, c, pos)
                    if best_c is None or key < best_key:
                        best_c = c
                        best_key = key
                        best_pos = pos
                    pos += 1

            if best_c is None:
                break
            route.insert(best_pos, best_c)
            load += demand(best_c)
            unserved.remove(best_c)

        routes.append(route)

    # Repair: if any customers remain due to edge cases, insert greedily into best feasible place.
    if unserved:
        for c in list(unserved):
            best_r = None
            best_pos = None
            best_inc = None
            for r_idx in range(len(routes)):
                r = routes[r_idx]
                if route_load(r) + demand(c) > capacity:
                    continue
                pos = 0
                while pos <= len(r):
                    inc = insertion_cost(r, pos, c)
                    if best_r is None or inc < best_inc:
                        best_r = r_idx
                        best_pos = pos
                        best_inc = inc
                    pos += 1
            if best_r is None:
                routes.append([c])
            else:
                routes[best_r].insert(best_pos, c)
            unserved.remove(c)

    # Local search: relocate customers between routes if it improves total cost.
    improved = True
    iter_count = 0
    while improved and iter_count < 4:
        improved = False
        iter_count += 1
        r1 = 0
        while r1 < len(routes):
            i = 0
            while i < len(routes[r1]):
                c = routes[r1][i]
                d_c = demand(c)
                best_move = None
                base_remove = None

                r = routes[r1]
                prev_n = depot if i == 0 else r[i - 1]
                next_n = depot if i + 1 == len(r) else r[i + 1]
                base_remove = dist(prev_n, next_n) - dist(prev_n, c) - dist(c, next_n)

                r2 = 0
                while r2 < len(routes):
                    if r2 != r1 and route_load(routes[r2]) + d_c <= capacity:
                        pos = 0
                        while pos <= len(routes[r2]):
                            add = insertion_cost(routes[r2], pos, c)
                            delta = base_remove + add
                            if delta < -1e-12:
                                key = (delta, r2, pos)
                                if best_move is None or key < best_move:
                                    best_move = key
                    r2 += 1

                if best_move is not None:
                    _, tr, pos = best_move
                    routes[r1].pop(i)
                    routes[tr].insert(pos, c)
                    improved = True
                    if i > 0:
                        i -= 1
                    continue
                i += 1
            r1 += 1

    # Remove empty routes.
    routes = [r for r in routes if len(r) > 0]
    return routes
